import math
def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    total_water = 0
    bucket_count = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                total_water += 1

    if total_water == 0:
        return bucket_count

    bucket_count += math.ceil(total_water / capacity)

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                grid[row][col] = 0

    return bucket_count

